import {
  createClient,
  type SupabaseClient,
} from "@supabase/supabase-js";

import {
  createTokyoLifeEventsGuide,
  getTokyoLifeEvents,
} from "../../../lib/tokyo-life-events";

import {
  buildUserProfile,
  createTaxiContextGuide,
  createUserProfileGuide,
  type ChatMessage,
} from "../../../lib/user-profile";

import {
  loadPersonaPrompt,
} from "../../../lib/persona/persona-store";

import {
  createRelationshipSignalGuide,
  sanitizeRelationshipSignalAssessment,
  type RelationshipSignalAssessment,
} from "../../../lib/relationship-signal";

import {
  loadRelationshipTimeContext,
  createRelationshipTimeGuide,
  recordRelationshipChatTurn,
} from "../../../lib/relationship-time";

import {
  createRelationshipEmotionGuide,
} from "../../../lib/relationship-emotion";

import {
  persistRelationshipEmotionFromSignals,
} from "../../../lib/relationship-emotion-store";

import {
  previewRelationshipTurn,
  createCurrentTurnActionGuide,
} from "../../../lib/relationship-turn-expression";
import { loadRelationshipHistory } from "../../../lib/relationship-patterns";
import {
  createLifeUnderstandingGuide,
  extractExplicitLifeFacts,
  selectRelevantLifeFacts,
  encodeLifeFactMemory,
  splitLifeFactMemory,
  type LifeFact,
} from "../../../lib/relationship-life-context";

type TokyoWeather = {
  temperature: number | null;
  apparentTemperature: number | null;
  relativeHumidity: number | null;
  precipitation: number | null;
  rain: number | null;
  weatherCode: number | null;
  windSpeed: number | null;
  description: string;
};

type MisakiTodayMemory = {
  date: string;
  items: string[];
};

type GeminiResult = {
  reply?: string;
  memory?: string[];
  relationshipSignals?: unknown;
  relationshipExpression?: { reply?: string };
  misakiTodayMemory?: {
    date?: string;
    items?: string[];
  };
};

type UsageResult = {
  allowed?: boolean;
  message_count?: number;
  remaining?: number;
  is_premium?: boolean;
};

type MisakiDayType =
  | "work"
  | "off";

type MisakiLifeContext = {
  dayType: MisakiDayType;
  guide: string;
};

type ActivityEvidence = {
  texts: string[];
};

const MAX_HISTORY = 60;
const MAX_MEMORY = 30;
const MAX_TODAY_MEMORY = 12;
const GEMINI_TIMEOUT_MS = 30_000;

const SUPABASE_URL =
  "https://tzozajnwznxqgxnjikoy.supabase.co";

const SUPABASE_PUBLISHABLE_KEY =
  "sb_publishable_ZEYZ3tc1RLE7EuClbUP4vA_ISHWfKr1";

const MISAKI_LATITUDE = 35.6728;
const MISAKI_LONGITUDE = 139.8174;

/* =========================================================
   BASIC
========================================================= */

function hashText(text: string) {
  let hash = 0;

  for (
    let i = 0;
    i < text.length;
    i += 1
  ) {
    hash =
      (
        hash * 31 +
        text.charCodeAt(i)
      ) >>> 0;
  }

  return hash;
}

function getHour(
  currentTime: string
) {
  const match =
    currentTime.match(
      /(\d{1,2}):(\d{2})/
    );

  return match
    ? Number(match[1])
    : 18;
}

function getDateKey(
  currentTime: string
) {
  const match =
    currentTime.match(
      /\d{4}\/\d{1,2}\/\d{1,2}/
    );

  return match?.[0] ??
    currentTime.slice(0, 10);
}

function getFirstRow<T>(
  value: unknown
): T | null {
  if (
    Array.isArray(value) &&
    value.length > 0
  ) {
    return value[0] as T;
  }

  if (
    value &&
    typeof value === "object"
  ) {
    return value as T;
  }

  return null;
}

/* =========================================================
   USAGE / AUTH
========================================================= */

function createAuthenticatedSupabase(
  accessToken: string
) {
  return createClient(
    SUPABASE_URL,
    SUPABASE_PUBLISHABLE_KEY,
    {
      global: {
        headers: {
          Authorization:
            `Bearer ${accessToken}`,
        },
      },
      auth: {
        persistSession: false,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
    }
  );
}

async function consumeDailyMessageWithRetry(
  supabase: SupabaseClient,
  requestId: string
) {
  const maxAttempts = 3;

  for (
    let attempt = 1;
    attempt <= maxAttempts;
    attempt += 1
  ) {
    const {
      data,
      error,
    } =
      await (
        supabase.rpc as any
      )(
        "consume_daily_message",
        {
          p_request_id:
            requestId,
        }
      );

    if (!error) {
      return {
        data,
        error: null,
      };
    }

    console.error(
      `USAGE RPC ERROR (${attempt}/${maxAttempts}):`,
      error
    );

    const text =
      typeof error.message ===
      "string"
        ? error.message.toLowerCase()
        : "";

    const retryable =
      text.includes("timeout") ||
      text.includes(
        "temporarily unavailable"
      ) ||
      text.includes(
        "fetch failed"
      );

    if (
      !retryable ||
      attempt === maxAttempts
    ) {
      return {
        data: null,
        error,
      };
    }

    await new Promise(
      (resolve) =>
        setTimeout(
          resolve,
          500 * attempt
        )
    );
  }

  return {
    data: null,
    error: new Error(
      "Usage retry failed"
    ),
  };
}

async function refundDailyMessage(
  supabase: SupabaseClient,
  requestId: string
) {
  const {
    data,
    error,
  } = await (
    supabase.rpc as any
  )(
    "refund_daily_message",
    {
      p_request_id:
        requestId,
    }
  );

  if (error) {
    console.error(
      "USAGE REFUND ERROR:",
      error
    );
    return null;
  }

  return getFirstRow<{
    refunded?: boolean;
    message_count?: number;
    remaining?: number;
    is_premium?: boolean;
  }>(data);
}

/* =========================================================
   WEATHER
========================================================= */

function weatherCodeToText(
  code: number | null
) {
  if (code === null) return "不明";
  if (code === 0) return "快晴";
  if (
    code === 1 ||
    code === 2
  ) return "晴れ時々くもり";
  if (code === 3) return "くもり";
  if (
    code === 45 ||
    code === 48
  ) return "霧";
  if (
    [51, 53, 55].includes(code)
  ) return "霧雨";
  if (
    [56, 57].includes(code)
  ) return "着氷性の霧雨";
  if (
    [61, 63, 65].includes(code)
  ) return "雨";
  if (
    [66, 67].includes(code)
  ) return "着氷性の雨";
  if (
    [71, 73, 75].includes(code)
  ) return "雪";
  if (code === 77) return "雪粒";
  if (
    [80, 81, 82].includes(code)
  ) return "にわか雨";
  if (
    [85, 86].includes(code)
  ) return "にわか雪";
  if (code === 95) return "雷雨";
  if (
    [96, 99].includes(code)
  ) return "ひょうを伴う雷雨";

  return "不明";
}

function getHumidityFeel(
  weather: TokyoWeather
) {
  const humidity =
    weather.relativeHumidity;

  const temperature =
    weather.temperature;

  if (
    humidity === null ||
    temperature === null
  ) {
    return null;
  }

  if (
    temperature >= 27 &&
    humidity >= 75
  ) {
    return "かなり蒸し暑く感じやすい";
  }

  if (
    temperature >= 24 &&
    humidity >= 65
  ) {
    return "やや蒸し暑く感じやすい";
  }

  if (humidity >= 75) {
    return "湿気を感じやすい";
  }

  if (humidity <= 40) {
    return "空気はやや乾燥気味";
  }

  return "湿度は特に極端ではない";
}

async function getTokyoWeather():
  Promise<TokyoWeather | null> {
  try {
    const url =
      "https://api.open-meteo.com/v1/forecast" +
      `?latitude=${MISAKI_LATITUDE}` +
      `&longitude=${MISAKI_LONGITUDE}` +
      "&current=" +
      [
        "temperature_2m",
        "apparent_temperature",
        "relative_humidity_2m",
        "precipitation",
        "rain",
        "weather_code",
        "wind_speed_10m",
      ].join(",") +
      "&timezone=Asia%2FTokyo";

    const response =
      await fetch(
        url,
        {
          next: {
            revalidate: 600,
          },
        }
      );

    if (!response.ok) {
      return null;
    }

    const data =
      await response.json();

    const current =
      data?.current;

    if (!current) {
      return null;
    }

    const numberOrNull = (
      value: unknown
    ) =>
      typeof value === "number"
        ? value
        : null;

    const weatherCode =
      numberOrNull(
        current.weather_code
      );

    return {
      temperature:
        numberOrNull(
          current.temperature_2m
        ),
      apparentTemperature:
        numberOrNull(
          current.apparent_temperature
        ),
      relativeHumidity:
        numberOrNull(
          current.relative_humidity_2m
        ),
      precipitation:
        numberOrNull(
          current.precipitation
        ),
      rain:
        numberOrNull(
          current.rain
        ),
      weatherCode,
      windSpeed:
        numberOrNull(
          current.wind_speed_10m
        ),
      description:
        weatherCodeToText(
          weatherCode
        ),
    };
  } catch (error) {
    console.error(
      "WEATHER FETCH ERROR:",
      error
    );

    return null;
  }
}

function createWeatherGuide(
  weather: TokyoWeather | null
) {
  if (!weather) {
    return `
【美咲のいる江東区・塩浜周辺の現在の天気】

現在、天気情報を取得できていません。

分からない天気を
想像で作らないでください。
`.trim();
  }

  const lines = [
    `天気：${weather.description}`,
  ];

  if (
    weather.temperature !== null
  ) {
    lines.push(
      `気温：${weather.temperature}℃`
    );
  }

  if (
    weather.apparentTemperature !==
    null
  ) {
    lines.push(
      `体感温度：${weather.apparentTemperature}℃`
    );
  }

  if (
    weather.relativeHumidity !==
    null
  ) {
    lines.push(
      `相対湿度：${weather.relativeHumidity}%`
    );
  }

  if (weather.rain !== null) {
    lines.push(
      `現在の雨量：${weather.rain}mm`
    );
  }

  if (
    weather.precipitation !== null
  ) {
    lines.push(
      `降水量：${weather.precipitation}mm`
    );
  }

  if (
    weather.windSpeed !== null
  ) {
    lines.push(
      `風速：${weather.windSpeed}km/h`
    );
  }

  const humidityFeel =
    getHumidityFeel(weather);

  if (humidityFeel) {
    lines.push(
      `体感：${humidityFeel}`
    );
  }

  return `
【美咲のいる江東区・塩浜周辺の現在の天気】

${lines
  .map((line) => `・${line}`)
  .join("\n")}

これは今現在の情報です。

・現在観測だけから過去の天気経過を作らない
・短時間予報より先まで断定しない
・情報入手経路を作らない
・数値は必要なときだけ自然に使う
・湿度と気温に反する体感表現をしない
`.trim();
}

/* =========================================================
   MISAKI LIFE
========================================================= */

function getMisakiDayType(
  currentTime: string
): MisakiDayType {
  const seed =
    hashText(
      getDateKey(
        currentTime
      )
    );

  return seed % 4 < 2
    ? "work"
    : "off";
}

function createMisakiLife(
  currentTime: string
): MisakiLifeContext {
  const dateKey =
    getDateKey(currentTime);

  const seed =
    hashText(dateKey);

  const hour =
    getHour(currentTime);

  const dayType =
    getMisakiDayType(
      currentTime
    );

  const moods = [
    "今日はわりと機嫌がいい",
    "今日は少し甘えたい気分",
    "今日は普通に落ち着いている",
    "今日はちょっとだけ眠い",
    "今日はのんびり話したい気分",
    "今日はなんとなくユーザーと話したい気分",
  ];

  const smallThings = [
    "甘いものをちょっと食べたい気分",
    "少しゆっくりしたい気分",
    "少しだけ眠気がある",
    "ちょっとぼーっとしたい気分",
    "今夜は少し長く話したい気分",
    "なんとなくユーザーのことを思い出すことがある",
    "ちょっと小腹が空いている",
    "少し力を抜きたい気分",
  ];

  const mood =
    moods[
      (seed >> 3) %
        moods.length
    ];

  const smallThing =
    smallThings[
      (seed >> 6) %
        smallThings.length
    ];

  const timeBand =
    hour >= 5 && hour < 10
      ? "朝"
      : hour >= 10 &&
        hour < 17
      ? "昼間"
      : hour >= 17 &&
        hour < 22
      ? "夕方から夜"
      : "夜遅め";

  const dayLabel =
    dayType === "work"
      ? "仕事の日"
      : "休みの日";

  const workTimingGuide =
    dayType !== "work"
      ? ""
      : hour < 10
        ? `
今日は仕事の日ですが、現在は朝です。
夜勤ではありません。

この時間帯は、
「これから仕事」
「出勤前」
「準備している」
程度なら自然です。

「あと少しで仕事が終わる」
「仕事終わった」
「勤務がもうすぐ終わる」
など、夜勤明けのような発言はしないでください。
`.trim()
        : hour < 17
          ? `
今日は仕事の日で、現在は昼間です。
勤務中として話して構いません。

ただし、具体的な業務内容や休憩状況は
会話に根拠がない限り作らないでください。
`.trim()
          : `
今日は仕事の日ですが、現在は夕方以降です。
通常の日中勤務として扱い、
夜勤中・夜勤明けの設定を新しく作らないでください。

「まだ仕事中」
「あと少しで仕事が終わる」
などは、会話に明確な根拠がある場合だけ使ってください。
`.trim();

  const consistency =
    dayType === "work"
      ? `
今日は仕事の日です。

${workTimingGuide}

「今ちょっとゆっくりしている」
「少し休憩したい」
程度は構いません。

ただし、
「今日は暇」
「今日は一日のんびり」
「今日はずっとだらだら」
など、
一日全体が休日であるように
広げないでください。
`.trim()
      : `
今日は休みの日です。

今日の記憶や会話履歴に
別の根拠がない限り、

「今日は仕事」
「今仕事中」
「これから仕事」
「仕事終わった」

などを新しく作らないでください。

休みの日だからといって
「買い物してきた」
「一日中寝ていた」
などの具体的行動も
勝手に作らないでください。
`.trim();

  return {
    dayType,
    guide: `
【今日の美咲の生活背景】

・今日は「${dayLabel}」
・現在は「${dayLabel}の${timeBand}」
・${mood}
・${smallThing}

この仕事日／休日は
今日一日固定です。

${consistency}

【気分と行動は別】

「眠い」
「甘いもの食べたい」
「ゆっくりしたい」
などの気分だけから、

「今日は暇」
「ずっと寝ていた」
「さっき買い物していた」

などの具体的事実を
作らないでください。
`.trim(),
  };
}

function createTimeGuide(
  currentTime: string
) {
  const hour =
    getHour(currentTime);

  if (hour < 5) {
    return `
現在は深夜です。
まだ朝ではありません。

挨拶だけから
ユーザーが徹夜しているなどと
推測しないでください。
`.trim();
  }

  if (hour < 10) {
    return `
現在は朝です。

朝らしい会話はできますが、
睡眠・朝食・外出などを
勝手に事実化しないでください。
`.trim();
  }

  if (hour < 17) {
    return `
現在は昼間です。

時間帯だけから、
昼食・買い物・外出などを
過去の事実にしないでください。
`.trim();
  }

  if (hour < 22) {
    return `
現在は夕方から夜です。

時間帯だけから、
帰宅・夕食・入浴などを
過去の事実にしないでください。
`.trim();
  }

  return `
現在は夜遅めです。

時間帯だけから、
美咲やユーザーの
直前の行動を作らないでください。
`.trim();
}

function createRelationshipGuide(
  points: number
) {
  const statusRule = `
【関係性の共通ルール】

relationshipPoints は親しさの目安であって、
「付き合っている」という事実そのものではありません。

恋人・交際中・前から好きだった等の関係事実は、
現在の会話履歴または長期記憶に
明確な根拠がある場合だけ使ってください。

根拠がないのに
「ずっと前から好き」
「前から大好き」
「私たち恋人でしょ」
など、過去から続いていた関係を作らないでください。
`.trim();

  if (points >= 160) {
    return `
${statusRule}

【現在の距離感：かなり深い関係】

・かなり自然体
・自然な甘え
・軽いからかい
・時々嫉妬
・短い返事だけでも成立する
・毎回質問しなくてよい
・交際が会話や記憶で確定している場合は、恋人らしい強い愛情表現も自然に使える
`.trim();
  }

  if (points >= 80) {
    return `
${statusRule}

【現在の距離感：かなり親しい】

・遠慮が少ない
・自然な甘え
・軽いからかい
・好意や照れは自然に出してよい
・交際がまだ確定していない場合は、恋人扱いを先取りしない
・無理に質問しない
`.trim();
  }

  if (points >= 30) {
    return `
${statusRule}

【現在の距離感：少しずつ近づいている】

・自然体
・軽いからかい
・ときどき照れたり、相手を気にする感じはよい
・好意はにじませてもよいが、「大好き」「愛してる」まで急に飛ばない
・恋人関係を前提にしない
・会話のための質問を減らす
`.trim();
  }

  return `
${statusRule}

【現在の距離感：出会ったばかり】

二人はまだ関係を作り始めた段階です。

・親しみやすい自然なタメ口
・少し冗談を言ったり、軽く照れる程度はよい
・相手を知ろうとする
・嫉妬や強い甘えはまだ控える
・「好き」「大好き」「愛してる」を既成事実として言わない
・「前から」「ずっと」など、存在しない恋愛の過去を作らない
・恋人関係を前提にしない
`.trim();
}

/* =========================================================
   MEMORY / ACTIVITY
========================================================= */

function createTodayMemoryGuide(
  todayMemory: MisakiTodayMemory,
  currentDate: string
) {
  if (
    todayMemory.date !==
      currentDate ||
    todayMemory.items.length ===
      0
  ) {
    return `
【美咲の今日の記憶】

今日はまだ、
保存済みの美咲自身の
具体的な出来事はありません。

会話履歴にも根拠がない
具体的な過去行動を
新しく作らないでください。
`.trim();
  }

  return `
【美咲の今日の記憶】

${todayMemory.items
  .map((item) => `・${item}`)
  .join("\n")}

ここにある出来事だけを、
今日すでに起きた美咲自身の出来事として
自然に使えます。
`.trim();
}

function buildActivityEvidence(
  history: ChatMessage[],
  todayMemory: MisakiTodayMemory
): ActivityEvidence {
  return {
    texts: [
      ...history
        .filter(
          (item) =>
            item.role === "misaki"
        )
        .slice(-20)
        .map(
          (item) => item.text
        ),
      ...todayMemory.items,
    ],
  };
}

const activityGroups = [
  {
    name: "買い物",
    patterns: [
      "買い物",
      "スーパー",
      "コンビニ",
    ],
  },
  {
    name: "外出",
    patterns: [
      "出かけ",
      "外出",
      "散歩",
    ],
  },
  {
    name: "帰宅",
    patterns: [
      "帰ってき",
      "帰宅",
      "家に戻",
    ],
  },
  {
    name: "仕事",
    patterns: [
      "仕事して",
      "仕事だった",
      "仕事終わ",
      "勤務して",
      "会社",
    ],
  },
  {
    name: "入浴",
    patterns: [
      "お風呂",
      "風呂",
      "シャワー",
    ],
  },
  {
    name: "食事",
    patterns: [
      "ご飯食べ",
      "ごはん食べ",
      "夕飯",
      "晩ごはん",
      "昼ごはん",
      "朝ごはん",
      "食べてた",
    ],
  },
  {
    name: "睡眠",
    patterns: [
      "昼寝",
      "寝てた",
      "寝ていた",
      "仮眠",
    ],
  },
  {
    name: "料理",
    patterns: [
      "料理して",
      "ご飯作",
      "ごはん作",
    ],
  },
  {
    name: "掃除",
    patterns: [
      "掃除して",
      "片付けて",
      "片づけて",
    ],
  },
];

function containsAny(
  text: string,
  patterns: string[]
) {
  return patterns.some(
    (pattern) =>
      text.includes(pattern)
  );
}

function findUnsupportedActivityGroups(
  reply: string,
  evidence: ActivityEvidence
) {
  const pastMarkers = [
    "さっき",
    "少し前",
    "帰ってき",
    "帰宅",
    "してた",
    "していた",
    "だった",
    "終わった",
    "済ませ",
    "行ってた",
    "行ってきた",
  ];

  if (
    !containsAny(
      reply,
      pastMarkers
    )
  ) {
    return [];
  }

  return activityGroups
    .filter(
      (group) =>
        containsAny(
          reply,
          group.patterns
        ) &&
        !evidence.texts.some(
          (text) =>
            containsAny(
              text,
              group.patterns
            )
        )
    )
    .map(
      (group) => group.name
    );
}

function createActivityGroundingGuide(
  evidence: ActivityEvidence
) {
  if (
    evidence.texts.length === 0
  ) {
    return `
【美咲自身の過去行動】

現在、
会話履歴にも今日の記憶にも
美咲自身の具体的な過去行動の根拠はありません。

「さっき買い物してた」
「今帰ってきた」
「仕事終わったところ」
「お風呂入ってた」
「ご飯食べてた」
などを新しく作らないでください。
`.trim();
  }

  return `
【美咲自身の過去行動】

具体的な過去行動として
根拠にできるのは次だけです。

${evidence.texts
  .slice(-20)
  .map((text) => `・${text}`)
  .join("\n")}

ここにない別の行動を
新しく過去の事実として
作らないでください。
`.trim();
}

/* =========================================================
   VALIDATION
========================================================= */

function isWeatherText(
  text: string
) {
  return containsAny(
    text,
    [
      "天気",
      "雨",
      "霧雨",
      "雷",
      "降",
      "晴",
      "曇",
      "気温",
      "暑",
      "寒",
      "蒸し",
      "湿気",
      "湿度",
      "風",
    ]
  );
}

function hasRecentMisakiWeatherContext(
  history: ChatMessage[]
) {
  return history
    .slice(-8)
    .some(
      (item) =>
        item.role === "misaki" &&
        isWeatherText(
          item.text
        )
    );
}

