import { createClient, type SupabaseClient } from "npm:@supabase/supabase-js@2.57.4";
import { loadPersonaPrompt } from "./persona-store.ts";
import { hasMisakiProactivePhotoOpportunity, selectMisakiProactivePhoto } from "./proactive-photo.ts";
import { buildProactiveDecisionContext, createProactiveDecisionGuide, type ProactiveDecisionContext } from "./proactive-decision.ts";
import { buildProactiveLifeContext, createProactiveLifeGuide } from "./proactive-life-context.ts";
import { deriveProactiveUrge, desireGuide, type ProactiveFocus } from "./proactive-urge.ts";
import { deriveProactiveMotive, motiveGuide, type ProactiveMotive, type RelationshipEventEvidence } from "./proactive-motive.ts";
import { hoursSinceLastContact } from "./contact-timing.ts";
import { focusGuide } from "./focus-guide.ts";
const SUPABASE_URL=Deno.env.get("SUPABASE_URL")!,MAX_PER_RUN=4,MIN_DELAY_MINUTES=55,MAX_DELAY_MINUTES=210;
type BodyClockRow={user_id:string;relationship_points:number;long_term_memory:unknown;today_memory:unknown;recent_history:unknown;notifications_enabled:boolean;timezone:string;pushes_today:number;push_date:string|null};
type ChatMessage={role:"user"|"misaki";text:string;sentAt?:string};
const randomDelayMs=()=>Math.floor(MIN_DELAY_MINUTES*60000+Math.random()*((MAX_DELAY_MINUTES-MIN_DELAY_MINUTES)*60000));
const tokyoNowText=()=>new Date().toLocaleString("ja-JP",{timeZone:"Asia/Tokyo",year:"numeric",month:"2-digit",day:"2-digit",weekday:"short",hour:"2-digit",minute:"2-digit",hour12:false});
function safeHistory(v:unknown):ChatMessage[]{return Array.isArray(v)?v.filter(x=>x&&(x.role==="user"||x.role==="misaki")&&typeof x.text==="string").map(x=>({role:x.role as "user"|"misaki",text:String(x.text).trim(),...(typeof x.sentAt==="string"?{sentAt:x.sentAt}:{})})).filter(x=>x.text).slice(-60):[]}
function safeMemory(v:unknown):string[]{return Array.isArray(v)?v.filter(x=>typeof x==="string"&&x.trim()).map(x=>x.trim()).slice(-30):[]}
function extractJsonObject(t:string){const s=t.trim();try{return JSON.parse(s)}catch{const a=s.indexOf("{"),b=s.lastIndexOf("}");if(a>=0&&b>a)return JSON.parse(s.slice(a,b+1));throw new Error("Gemini returned invalid JSON")}}
async function generateMessage(key:string,persona:string,history:ChatMessage[],memory:string[],decision:ProactiveDecisionContext,currentTime:string,desirePrompt:string,focusPrompt:string,motive:ProactiveMotive){const recent=history.slice(-20).map(m=>`${m.role==="user"?"ユーザー":"美咲"}: ${m.text}`).join("
"),life={situation:decision.situation,plan:decision.plan,evidence:decision.lifeEvidence,confidence:decision.lifeConfidence};const prompt=`${persona}

${createProactiveDecisionGuide(decision)}

${createProactiveLifeGuide(life)}

【美咲の今の欲求】
${desirePrompt}

【今の気持ちが向いている先】
${focusPrompt}

${motiveGuide(motive)}

【美咲の体内時計からの自発メッセージ】
これはユーザーへの返答ではなく、美咲から自然に送る短いLINEです。
現在時刻（日本時間）: ${currentTime}
関係性ポイント: ${decision.relationshipPoints}
長期記憶:
${memory.length?memory.map(x=>`・${x}`).join("
"):"なし"}
最近の会話:
${recent||"なし"}

ルール:
・1〜2文を基本にする
・毎回質問で終わらせない
・ユーザーの現在地、勤務中、休み、体調、予定などは生活文脈の明示的根拠がある範囲だけ使う
・古い予定を現在進行形だと断定しない
・過去の出来事を会話や記憶にないのに作らない
・AI、システム、通知、体内時計、タグ名、内部状態を出さない
・JSON以外は出力しない
出力:{"reply":"美咲のメッセージ"}`;const response=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent?key=${key}`,{method:"POST",signal:AbortSignal.timeout(25000),headers:{"Content-Type":"application/json"},body:JSON.stringify({contents:[{role:"user",parts:[{text:prompt}]}],generationConfig:{temperature:.95,responseMimeType:"application/json"}})});if(!response.ok)throw new Error(`Gemini error: ${response.status}`);const data=await response.json(),raw=data?.candidates?.[0]?.content?.parts?.map((p:{text?:string})=>p?.text||"").join("")||"",parsed=extractJsonObject(raw),reply=typeof parsed?.reply==="string"?parsed.reply.trim():"";if(!reply)throw new Error("Gemini reply was empty");return{reply,currentTime}}
async function relayPush(id:string){const ts=String(Date.now()),signer=createClient(SUPABASE_URL,Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,{auth:{persistSession:false,autoRefreshToken:false}}),{data:hex,error}=await signer.rpc("sign_misaki_body_clock_relay",{p_timestamp:ts,p_delivery_id:id});if(error||typeof hex!=="string"||!/^[a-f0-9]{64}$/.test(hex))throw new Error("relay_signing_unavailable");const r=await fetch("https://misaki38-ai.com/api/push/body-clock",{method:"POST",redirect:"error",signal:AbortSignal.timeout(45000),headers:{"Content-Type":"application/json","x-body-clock-time":ts,"x-body-clock-signature":hex},body:JSON.stringify({deliveryId:id})}),d=await r.json().catch(()=>({error:"invalid_relay_response"}));if(!r.ok)throw new Error(`push_relay_${r.status}:${d.error||"send_failed"}`);return d}
async function processUser(s:SupabaseClient,key:string,row:BodyClockRow){const{data:lease,error:le}=await s.from("background_push_state").select("next_push_at").eq("user_id",row.user_id).single();if(le||!lease?.next_push_at)throw new Error("lease_missing");const currentTime=tokyoNowText(),history=safeHistory(row.recent_history),memory=safeMemory(row.long_term_memory),points=Math.max(0,Number(row.relationship_points)||0),life=buildProactiveLifeContext(history,memory),{data:re,error:ree}=await s.from("misaki_relationship_events").select("event_type,reason,created_at,metadata").eq("user_id",row.user_id).eq("event_type","emotion_action_v2_after_chat").order("created_at",{ascending:false}).limit(40);if(ree)throw ree;const sharedRelationshipEvents=Array.isArray(re)?re:[],decision=await buildProactiveDecisionContext(s,row.user_id,points,life,currentTime,sharedRelationshipEvents),photoOpportunity=hasMisakiProactivePhotoOpportunity({currentTime,decision}),urge=deriveProactiveUrge({relationshipStoryMeaning:decision.relationshipStoryMeaning,photoOpportunity,action:decision.action,emotion:decision.emotion,emotionIntensity:decision.emotionIntensity,lifeConfidence:decision.lifeConfidence,intimacyLevel:decision.intimacyLevel,pushesToday:row.pushes_today,hoursSinceLastContact:hoursSinceLastContact(history)});const relationshipEvents:RelationshipEventEvidence[]=sharedRelationshipEvents.slice(0,3).map((e:any,index:number)=>({eventType:String(e.event_type||""),reason:String(e.reason||""),createdAt:String(e.created_at||""),...(typeof e.metadata?.direction==="string"?{direction:e.metadata.direction}:{}),...(index===0?{storyMeaning:decision.relationshipStoryMeaning}:{})})).filter(e=>e.reason&&e.createdAt):[];const motive=deriveProactiveMotive({desire:urge.desire,focus:urge.focus,history,memory,lifeEvidence:decision.lifeEvidence,relationshipEvents});if(!urge.shouldSend){const{data:nf,error:nfe}=await s.rpc("finish_misaki_body_clock_no_action",{p_user_id:row.user_id,p_lease_until:lease.next_push_at,p_delay_minutes:Math.floor(randomDelayMs()/60000)});if(nfe)throw nfe;const{error:se}=await s.from("misaki_relationship_events").insert({user_id:row.user_id,event_type:"proactive_no_action",reason:urge.reason,metadata:{emotion:decision.emotion,emotionIntensity:decision.emotionIntensity,action:decision.action,direction:decision.direction,desire:urge.desire,urgeStrength:urge.strength,motive}});if(se)console.error("PROACTIVE_NO_ACTION_EVENT_FAILED",row.user_id);return{userId:row.user_id,skipped:true,reason:urge.reason,desire:urge.desire,emotion:decision.emotion,action:decision.action,direction:decision.direction,urgeStrength:urge.strength,nextPushAt:nf?.nextPushAt??null,pushesToday:nf?.pushesToday??row.pushes_today,push:{sent:0,removed:0,skipped:"no_internal_urge"}}}const persona=await loadPersonaPrompt(s,row.user_id,"proactive"),{reply}=await generateMessage(key,persona.text,history,memory,decision,currentTime,desireGuide(urge.desire),focusGuide(urge.focus),motive);const{data:rp,error:pe}=await s.from("misaki_proactive_deliveries").select("photo_id").eq("user_id",row.user_id).not("photo_id","is",null).order("created_at",{ascending:false}).limit(8);if(pe)throw pe;const recent=Array.isArray(rp)?rp.map(x=>typeof x?.photo_id==="string"?x.photo_id:"").filter(Boolean):[],photo=selectMisakiProactivePhoto({currentTime,reply,decision,desire:urge.desire,urgeStrength:urge.strength,recentPhotoIds:recent}),photoContext={...decision,currentTime,selectorVersion:4,source:"body_clock"};const{data:f,error:fe}=await s.rpc("finish_misaki_body_clock_delivery",{p_user_id:row.user_id,p_lease_until:lease.next_push_at,p_message:reply,p_photo_id:photo?.id??null,p_photo_src:photo?.src??null,p_photo_context:photoContext,p_delay_minutes:Math.floor(randomDelayMs()/60000)});if(fe)throw fe;const{error:ee}=await s.from("misaki_relationship_events").insert({user_id:row.user_id,event_type:"proactive_decision",reason:decision.reason,metadata:{decision,urge,motive,delivery_id:f.deliveryId,photo_id:photo?.id??null,selector_version:4}});if(ee)console.error("PROACTIVE_DECISION_EVENT_FAILED",row.user_id);const push=row.notifications_enabled?await relayPush(f.deliveryId):{sent:0,removed:0,skipped:"notifications_disabled"};return{userId:row.user_id,deliveryId:f.deliveryId,desire:urge.desire,urgeStrength:urge.strength,direction:decision.direction,action:decision.action,emotion:decision.emotion,lifeConfidence:decision.lifeConfidence,photoId:photo?.id??null,nextPushAt:f.nextPushAt,pushesToday:f.pushesToday,push}}
export async function handler(req:Request){if(req.method!=="POST")return Response.json({error:"method_not_allowed"},{status:405});const secret=req.headers.get("x-cron-secret");if(!secret||secret.length!==64)return Response.json({error:"unauthorized_header",version:5},{status:401});const sk=Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");if(!sk||!SUPABASE_URL)return Response.json({error:"admin_config_missing"},{status:503});const s=createClient(SUPABASE_URL,sk,{auth:{persistSession:false,autoRefreshToken:false}}),{data:authorized,error:ae}=await s.rpc("verify_misaki_body_clock_secret",{p_secret:secret});if(ae)return Response.json({error:"auth_unavailable"},{status:503});if(authorized!==true)return Response.json({error:"unauthorized_secret",version:5},{status:401});const key=Deno.env.get("GEMINI_API_KEY");let relayReady=false,relayError:string|null=null;try{relayReady=(await relayPush("health")).ok===true}catch(e){relayError=e instanceof Error?e.message:"relay_unavailable"}const ready={gemini:!!key,pushRelay:relayReady};if(new URL(req.url).searchParams.get("mode")==="health")return Response.json({ok:Object.values(ready).every(Boolean),ready,relayError,version:"body-clock-grounded-life-v4"});if(!Object.values(ready).every(Boolean))return Response.json({error:"configuration_not_ready",ready,relayError},{status:503});const limit=Math.max(1,Math.min(MAX_PER_RUN,Number(new URL(req.url).searchParams.get("limit"))||MAX_PER_RUN)),{data,error}=await s.rpc("claim_misaki_body_clock_due_users",{p_limit:limit});if(error)return Response.json({error:"claim_failed"},{status:500});const rows=(data||[])as BodyClockRow[],results:any[]=[];let cursor=0;const worker=async()=>{while(cursor<rows.length){const row=rows[cursor++];try{const r=await processUser(s,key!,row);results.push({ok:!("failed"in r.push)||r.push.failed===0,...r})}catch(e){console.error("BODY_CLOCK_USER_FAILED",row.user_id);results.push({ok:false,userId:row.user_id,error:e instanceof Error?e.message:"delivery_failed"})}}};await Promise.all([worker(),worker(),worker(),worker()]);return Response.json({ok:results.every(r=>r.ok),checkedAt:new Date().toISOString(),claimed:rows.length,results},{status:results.every(r=>r.ok)?200:500})}Deno.serve(handler);

