index 3f25cbb..13768be 100644
--- a/supabase/functions/body-clock/proactive-decision.ts
+++ b/supabase/functions/body-clock/proactive-decision.ts
@@ -3,7 +3,7 @@ import type { ProactiveLifeContext } from "./proactive-life-context.ts";

 export type ProactiveDirection = "MISAKI" | "USER" | "US" | "MISAKI_TO_USER" | "MISAKI_TO_US";
 export type RelationshipAction = "NORMAL" | "WAIT" | "TEASE" | "SULK" | "CHASE" | "PULL" | "RECONNECT";
-export type RelationshipEmotion = "neutral" | "happy" | "lonely" | "sulky" | "concerned" | "affectionate";
+export type RelationshipEmotion = "neutral" | "happy" | "affectionate" | "concerned" | "hurt" | "sulky" | "guarded";
 export type ProactiveExpressionTag =
   | "soft"
   | "cheerful"
@@ -17,6 +17,8 @@ export type ProactiveExpressionTag =
   | "encouraging"
   | "check_in";

+export type RelationshipStoryMeaning = "none" | "unresolved_hurt" | "repair_in_progress" | "repair_demonstrated" | "repeated_harm";
+
 export type ProactiveDecisionContext = {
   shouldSend: true;
   reason: "claimed_after_relationship_action_gate";
@@ -32,15 +34,41 @@ export type ProactiveDecisionContext = {
   lifeEvidence: string[];
   lifeConfidence: "none" | "explicit";
   tags: ProactiveExpressionTag[];
+  relationshipStoryMeaning: RelationshipStoryMeaning;
 };

 type RelationshipRow = {
-  intimacy_level?: number | null;
+  intimacy_level?: string | number | null;
   emotion_state?: { primary?: string; intensity?: number } | null;
   action_state?: string | null;
   last_interaction_at?: string | null;
 };

+
+export function storyMeaningFromEvents(events: Array<{ metadata?: unknown; created_at?: string }>): RelationshipStoryMeaning {
+  let unresolvedHurt = 0;
+  let repairStage: "none" | "hurt" | "repair_attempted" | "rebuilding" = "none";
+  let meaning: RelationshipStoryMeaning = "none";
+  let harmCount = 0;
+  const limited=[...events].slice(0,40);
+  const hasCompleteTimestamps=limited.every(e=>typeof e?.created_at==="string"&&Number.isFinite(new Date(e.created_at).getTime()));
+  const ordered = hasCompleteTimestamps ? limited.sort((a,b)=>new Date(a.created_at!).getTime()-new Date(b.created_at!).getTime()) : limited.reverse();
+  const weight = (s: any) => { const strength=Number.isFinite(s?.strength)?Number(s.strength):0, confidence=Number.isFinite(s?.confidence)?Number(s.confidence):0; return strength*confidence; };
+  for (const event of ordered) {
+    const metadata = event?.metadata && typeof event.metadata === "object" ? event.metadata as any : {};
+    const rawSignals = metadata.signal_summary ?? metadata.signals;
